<?php
declare(strict_types=1);
namespace Nerozon\Http;
use Nerozon\Questionnaire\{SubmitQuestionnaire,UnsupportedQuestionnaire,UnsupportedQuestionnaireVersion,InvalidQuestionnaireSubmission,QuestionnairePersistenceFailed};
final class HttpConnector{public function __construct(private SubmitQuestionnaire $submit,private int $maxBytes=65536){}public function dispatch(string $method,string $path,string $contentType,string $body):array{if($path!=='/v1/questionnaire/submissions')return $this->error(404,'not_found');if($method!=='POST')return $this->error(405,'method_not_allowed');if(strtolower(trim(explode(';',$contentType)[0]))!=='application/json')return $this->error(415,'unsupported_media_type');if(strlen($body)>$this->maxBytes)return $this->error(413,'request_too_large');try{$d=json_decode($body,true,512,JSON_THROW_ON_ERROR);if(!is_array($d)||array_is_list($d)||array_diff(array_keys($d),['questionnaire_id','questionnaire_version','answers'])||!isset($d['questionnaire_id'],$d['questionnaire_version'],$d['answers']))throw new InvalidQuestionnaireSubmission('Invalid request shape');return [201,['Content-Type'=>'application/json'],$this->submit->execute($d)];}catch(\JsonException|UnsupportedQuestionnaire|UnsupportedQuestionnaireVersion|InvalidQuestionnaireSubmission){return $this->error(400,'invalid_request');}catch(QuestionnairePersistenceFailed|\Throwable){return $this->error(500,'internal_error');}}private function error(int $s,string $c):array{return [$s,['Content-Type'=>'application/json'],['error'=>['code'=>$c,'message'=>'Request could not be processed.']]];}}
